// The browser client parses each shared fixture exactly as the terminal
// client's reference does (ADR 0054). The fixtures are generated by the
// reference: `KIT_UPDATE_FIGURE_FIXTURES=1 ard test test/figure_fixtures_test.ard`
// in `apps/cli`. Each records the parsed figure, then the terminal's drawing
// or layout, which this client doesn't make; or the reason the figure isn't drawn.
import { describe, expect, test } from "bun:test";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { cut, fenced, guides, isFigure, parseFigure, record } from "./figure";
import { fixed } from "./grammar";

const directory = join(import.meta.dir, "../../../../testdata/figures");
const names = readdirSync(directory)
  .filter((file) => file.endsWith(".md"))
  .map((file) => file.slice(0, -3))
  .sort();

/** A fixture's info string and body, as a fenced block holds them. */
function fence(source: string): { info: string; body: string } {
  const lines = source.replace(/^[\r\n]+|[\r\n]+$/g, "").split("\n");
  return { info: (lines[0] ?? "").replace(/^[`~]+/, ""), body: lines.slice(1, -1).join("\n") };
}

describe("figure fixtures", () => {
  test("are present", () => {
    expect(names.length).toBeGreaterThanOrEqual(50);
  });

  test.each(names)("%s parses like the reference", (name) => {
    const source = readFileSync(join(directory, `${name}.md`), "utf8");
    const recorded = readFileSync(join(directory, `${name}.txt`), "utf8");
    // The parsed figure is everything before the drawing or layout.
    const cut = recorded.search(/\n(drawn|laid out) /);
    const expected = cut < 0 ? recorded : recorded.slice(0, cut + 1);
    const { info, body } = fence(source);
    const parsed = parseFigure(info, body);
    expect(parsed.ok ? record(parsed.value) : `not drawn: ${parsed.error.reason}\n`).toBe(expected);
  });
});

describe("figures", () => {
  test("are named by the first word of the info string, exactly", () => {
    expect(isFigure('bars title="Routes"')).toBe(true);
    expect(isFigure("stack")).toBe(true);
    expect(isFigure("Bars")).toBe(false);
    expect(isFigure("plot")).toBe(false);
    expect(isFigure("ts")).toBe(false);
  });

  test("tree guides join each node to its parent", () => {
    const parsed = parseFigure("tree", "- src\n  - a\n    - deep\n  - b\n- docs");
    if (!parsed.ok) throw new Error(parsed.error.reason);
    expect(guides(parsed.value.items)).toEqual([[], ["branch"], ["through", "last"], ["last"], []]);
  });

  test("copy as the fence an author would paste back", () => {
    expect(fenced('bars title="Routes"', "- /docs: 12,400")).toBe(
      '```bars title="Routes"\n- /docs: 12,400\n```',
    );
    expect(fenced("spec", "- Run: ```go test```")).toBe("````spec\n- Run: ```go test```\n````");
  });

  test("cut long labels to 32 characters, counting what a reader sees", () => {
    expect(cut("short")).toBe("short");
    expect(cut("a".repeat(40))).toBe(`${"a".repeat(31)}…`);
    expect(cut("👩‍💻".repeat(33))).toBe(`${"👩‍💻".repeat(31)}…`);
  });

  test("write computed numbers as printf does, from the exact binary value", () => {
    // 0.0000025 is slightly above the tie in binary, so it rounds up.
    expect(fixed(0.0000025, 6)).toBe("0.000003");
    expect(fixed(0.0000015, 6)).toBe("0.000002");
    // Exact ties go to even.
    expect(fixed(0.5, 0)).toBe("0");
    expect(fixed(1.5, 0)).toBe("2");
    expect(fixed(2.5, 0)).toBe("2");
    expect(fixed(0.125, 2)).toBe("0.12");
    expect(fixed(0, 3)).toBe("0.000");
    expect(fixed(12400, 0)).toBe("12400");
    expect(fixed(1e18, 2)).toBe("1000000000000000000.00");
    expect(fixed(0.1 + 0.2, 6)).toBe("0.300000");
  });
});
